// Device controls only. This page has no cloud credentials or order API client.
export const DEVICE_KEYS=Object.freeze({
 strategies:['league_strategy_library_v1'],
 notes:['league_tools_v1'],
 preferences:['league_theme_v2','league_cloud_server']
});
const keys=Object.values(DEVICE_KEYS).flat();
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function deviceInventory(storage){return keys.map(key=>{const raw=storage.getItem(key);return {key,present:raw!==null,bytes:raw===null?0:new TextEncoder().encode(raw).length};});}
export function exportDeviceData(storage){return {schema_version:1,type:'league_device_data',exported_at:new Date().toISOString(),scope:'This browser only; excludes cloud account, credentials and hosting-provider cookies.',values:Object.fromEntries(keys.map(key=>[key,storage.getItem(key)]).filter(([,value])=>value!==null))};}
export function clearDeviceCategory(storage,category){
 const selected=category==='all'?keys:Object.hasOwn(DEVICE_KEYS,category)?DEVICE_KEYS[category]:null;
 if(!selected)throw Error('Choose a supported device-data category.');
 for(const key of selected)storage.removeItem(key);
}
const row=(label,text)=>`<div class="privacy-row"><strong>${e(label)}</strong><p>${e(text)}</p></div>`;
export function privacyPage(inventory=[],message=''){
 return `<header class="privacy-header"><a class="privacy-brand" href="./#terminal">LL <span>LAST OF OUR LEAGUE</span></a><a class="btn" href="./#terminal">Return to workspace</a></header>
 <p class="eyebrow">YOUR WORKSPACE · YOUR DATA</p><h1>Privacy & usage</h1><p class="subheading">Understand what is stored, who can see it and how to manage this device.</p><p class="privacy-meta">Notice version 1 · Updated 23 November 2026 · Automatic options paper trading</p>
 <nav class="privacy-links" aria-label="Privacy sections"><a href="#privacy">Privacy notice</a><a href="#usage">Usage rules</a><a href="#device">Device controls</a><a href="#providers">Providers & licences</a></nav>
 <section class="panel privacy-card"><h2>Invited research workspace</h2><p>This is one shared virtual account for invited users. It has no customer registration, paid subscription or broker execution. The public website shows a saved research snapshot; private account details require a separate engine sign-in.</p><p><strong>Operator identity and public privacy contact are awaiting confirmation.</strong> Existing invited users can contact the workspace owner through the channel used to receive their access key. Do not send keys, identity documents or payment details. A complete operator notice and legal assessment are required before wider customer use.</p></section>
 <section id="privacy" class="panel privacy-card"><h2>Privacy notice</h2>
 ${row('Cloud account and access','The engine processes your assigned username, role, authentication credential and paper-trading controls to authenticate access and maintain the shared account. The client keeps its access key in page memory; it does not intentionally write it to browser storage or report exports. Closing or navigating away from the app ends that page session. Keep your key private.')}
 ${row('Shared account visibility','Authorized users can see the same virtual balance, positions, orders and strategy activity. This is not a separate private portfolio for each username. Browser notes and research drafts are device-local unless you deliberately export or share them.')}
 ${row('Device storage','Saved strategy definitions and test summaries, review notes, device alerts, theme and the chosen engine address use this origin’s local storage. They remain until you remove them or clear browser data. The app also caches static assets for offline access; authenticated API data is excluded from that cache. Do not place sensitive personal information in notes.')}
 ${row('Network and security records','Your browser sends network metadata such as IP address to the hosting service and, when connected, the engine. The engine uses IP addresses in memory for rate limiting. Its audit records contain username, action, status, time and request ID. Error and infrastructure logs may contain technical metadata. The application does not intentionally log access keys.')}
 ${row('Purpose and processing basis','Data supports requested workspace features, access control, security, research records and recovery. These purposes are documented; the operator must establish and record the applicable legal basis for each purpose and jurisdiction. This notice does not establish consent for marketing or certify GDPR/DPDP compliance.')}
 ${row('Retention','Device data: until you remove it. Cloud trading history: retained for account continuity, with no automatic age-based deletion currently configured. Operational audit: latest 20,000 events, not a fixed time period. Completed idempotency entries: cleaned after seven days when new requests are claimed; pending records can persist. Local backups: latest 24 snapshots. Off-server backups: seven-day lifecycle plus seven-day soft deletion; expired copies are not immediately erased. Monitoring logs: configured for 30 days; infrastructure/provider retention is separate.')}
 ${row('Access, correction and deletion requests','Use the controls below for this device. For server records, contact the workspace owner using your existing access channel. Specify access, correction, export, objection or deletion without including your key. The operator must verify identity, review applicable rights and deadlines, and protect the other user’s shared records. Device deletion does not delete the cloud account or backups. There is no automated server-account deletion endpoint.')}
 ${row('Security and incidents','Existing safeguards include authenticated roles, restricted origins, HTTPS, private backups and operational monitoring. No system is guaranteed secure. Report suspected exposure to the workspace owner without sending the exposed key. The owner must contain the incident, assess affected data and applicable notification duties, and communicate through verified channels.')}
 </section>
 <section id="usage" class="panel privacy-card"><h2>Usage rules & trading limitations</h2><p>Use only your assigned access and authorized paper controls. Do not share keys, attempt access to another role, upload unlawful content or overload the service. Both users operate one shared virtual account; agree with the owner who controls start and pause.</p><p>Option premiums and fills are modelled. Backtests, research forecasts and paper performance do not establish real execution or future returns. Data failures can delay simulated exits. This service does not accept deposits, execute broker orders or provide a profit guarantee.</p><p>The app has no checkout, customer billing, renewal, cancellation charge or marketing-message system. Cloud hosting costs belong to the hosting account owner. Commercial fees or marketing would require separate disclosures and any applicable opt-in before launch.</p><p>These are current workspace rules and limitations, not an executed customer contract. The operator must approve ownership, appropriate terms and jurisdiction before a commercial launch. No click-through legal agreement has been introduced.</p></section>
 <section id="device" class="panel privacy-card"><h2>Manage this browser</h2><p>Export first if you want a copy. Exports can contain private notes and strategy ideas; keep the downloaded file private. Other open workspace tabs may still hold data in memory, so close them before clearing. These controls do not stop the cloud engine or delete its shared history.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>App storage key</th><th>Stored</th><th>Bytes</th></tr></thead><tbody>${inventory.map(item=>`<tr><td>${e(item.key)}</td><td>${item.present?'Yes':'No'}</td><td>${e(item.bytes)}</td></tr>`).join('')}</tbody></table></div><div class="privacy-controls"><button class="btn" data-privacy="export">Export device data</button><label>Data to clear<select id="privacy-category" class="select"><option value="notes">Notes and device alerts</option><option value="strategies">Saved strategy drafts</option><option value="preferences">Theme and engine address</option><option value="all">All listed app data</option></select></label><button class="btn" data-privacy="clear">Clear selected device data</button><button class="btn" data-privacy="cache">Clear offline app cache</button></div><p id="privacy-message" role="status" aria-live="polite">${e(message)}</p><p>The controls cover the listed application keys and League static cache only. Hosting-provider cookies, browser history and downloaded files are managed through your browser or device settings.</p></section>
 <section id="providers" class="panel privacy-card"><h2>Providers, cookies & licences</h2>
 ${row('Hosting and recovery','The static website is hosted through ChatGPT Sites. The engine, private recovery storage and external monitoring use Microsoft Azure. The VM and recovery storage are in India South Central; availability probes run in multiple regions. Provider-side processing, subprocessors and international transfers require operator review of the relevant agreements. No claim is made that all metadata stays in India.')}
 ${row('Market data','The engine uses an external public underlying/VIX research feed. There is no licensed live option-chain account connected. Provider rights, redistribution permissions and commercial use must be reviewed before extending use. Market-data requests and retention follow the provider’s own terms.')}
 ${row('Cookies and local storage','The application source includes no advertising, behavioural analytics or marketing SDK and does not set its own tracking cookies. Local storage is used for the requested workspace features described above. Hosting providers may use their own security/session technologies. No optional tracking is being enabled by this notice; adding it requires a separate assessment and a working consent/withdrawal mechanism where applicable.')}
 ${row('Code and assets','Third-party packages remain subject to their licences. Application code, branding and dissertation-derived material have no newly assigned open-source licence. Ownership and redistribution permission require operator confirmation; a university submission does not by itself establish commercial rights.')}
 <p><a href="third-party-notices.txt" download>Download bundled Python third-party notices</a>. The inventory covers the locked application wheels and bootstrap pip wheel, including bundled notices where provided. Container images, operating-system components, hosting services and market-data rights require separate review.</p>
 <p class="privacy-meta">A privacy page alone does not establish legal compliance. Applicability depends on the operator, users, location and purposes. See official <a href="https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/personal-information-what-is-it/who-does-the-uk-gdpr-apply-to" rel="noreferrer">ICO scope guidance</a> and <a href="https://www.meity.gov.in/documents/act-and-policies/digital-personal-data-protection-rules-2025-gDOxUjMtQWa?pageTitle=Digital-Personal-Data-Protection-Rules-2025-2" rel="noreferrer">India’s DPDP rules</a>.</p></section><footer class="privacy-meta">Last of Our League · Paper research workspace · <a href="./#terminal">Return to trading terminal</a></footer>`;
}
if(typeof document!=='undefined'){
 let storage;try{storage=globalThis.localStorage;}catch{}
 const root=document.querySelector('#privacy-center');
 const render=(message='')=>{let inventory=[];try{inventory=deviceInventory(storage);}catch{message='Device storage is unavailable. Use your browser settings to inspect or remove app data.';}root.innerHTML=privacyPage(inventory,message);};
 render();
 document.addEventListener('click',async event=>{
  const action=event.target.closest('[data-privacy]')?.dataset.privacy;if(!action)return;
  try{
   if(action==='export'){
    const url=URL.createObjectURL(new Blob([JSON.stringify(exportDeviceData(storage),null,2)],{type:'application/json'}));
    const a=document.createElement('a');a.href=url;a.download='league-private-device-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);render('Device export downloaded. It excludes the cloud account and access keys.');
   }else if(action==='clear'){
    const category=document.querySelector('#privacy-category').value;
    if(!globalThis.confirm('Permanently remove '+({notes:'notes and device alerts',strategies:'saved strategy drafts',preferences:'theme and remembered engine address',all:'all listed app data'}[category]||'selected data')+' from this browser? Export a copy first. The cloud account and engine are unchanged.'))return;
    clearDeviceCategory(storage,category);render('Selected device data cleared. The cloud engine and shared account were not changed.');
   }else if(action==='cache'){
    if(!globalThis.caches)throw Error('Offline cache controls are unavailable in this browser.');
    const names=await caches.keys();await Promise.all(names.filter(name=>name.startsWith('league-shell-')).map(name=>caches.delete(name)));render('League offline cache cleared. Online access is needed to load app assets again.');
   }
  }catch(error){render('Could not complete the action: '+error.message);}
 });
}
